using AccountingAutomationHub.Infrastructure.Banking;
using AccountingAutomationHub.Infrastructure.Spreadsheets;

namespace AccountingAutomationHub.Desktop.Services;

/// <summary>
/// Exact identity markers for workbooks generated by AAH itself. These markers let
/// Auto Import distinguish a blank user-fillable template from an unknown/failed
/// accounting source and route completed workbooks to the correct module without
/// relying on filename or heuristic header scores.
/// </summary>
public static class GeneratedAccountingWorkbookIdentity
{
    public const string JournalMetaSheetName = "__AAH_JOURNAL_META";
    public const string JournalWorkbookKind = "Accounting Automation Hub Journal Import";
    public const string CashMetaSheetName = "__AAH_CASH_META";
    public const string CashWorkbookKind = "Accounting Automation Hub Cash Entry Import";

    public static bool IsJournalWorkbook(OpenXmlWorkbookData workbook) =>
        ReadKind(workbook, JournalMetaSheetName)
            .Equals(JournalWorkbookKind, StringComparison.OrdinalIgnoreCase);

    public static bool IsCashWorkbook(OpenXmlWorkbookData workbook) =>
        ReadKind(workbook, CashMetaSheetName)
            .Equals(CashWorkbookKind, StringComparison.OrdinalIgnoreCase);

    private static string ReadKind(OpenXmlWorkbookData workbook, string metaSheetName) =>
        BankSuspenseWorkbookService.ReadWorkbookMeta(workbook, metaSheetName, "Kind");
}
